const controls=$('.analytics-controls');const pLabel=document.createElement('label');pLabel.innerHTML='품목 <select id="analysisProduct">'+Object.entries(productNames).map(([v,n])=>`<option value="${v}">${n}</option>`).join('')+'</select>';controls.insertBefore(pLabel,controls.children[1]);$('#analysisChannel').insertAdjacentHTML('beforeend','<option value="global">글로벌</option>');
const originalValues=values;values=function(){const month=$('#analysisMonth').value,channel=$('#analysisChannel').value,product=$('#analysisProduct').value;let out={};for(const period of ['current','lastYear','lastMonth','target']){const shares=period==='lastYear'?[.57,.34,.09]:period==='target'?[.62,.30,.08]:[.60,.32,.08];const split=(arr,pi)=>arr.map((n,i)=>{const w=i===3?[.5,.4,.1]:shares;const a=i>=3&&i!==6?Math.round(n*w[0]):n*w[0];const b=i>=3&&i!==6?Math.round(n*w[1]):n*w[1];return [a,b,n-a-b][pi]});const online=fixtures[month].online[period];const off=fixtures[month].offline[period];const global=off.map((n,i)=>i>=3&&i!==6?Math.round(n*.15):n*.15);const offline=off.map((n,i)=>n-global[i]);const source=channel==='all'?online.map((n,i)=>n+off[i]):channel==='online'?online:channel==='global'?global:offline;out[period]=product==='all'?source:split(source,['jewelry','bags','romanson'].indexOf(product));}return out};
