const baseAnalysis=drawAnalysis;drawAnalysis=function(){const isProducts=analysisType==='products';const savedType=analysisType;if(isProducts)analysisType='sales';baseAnalysis();analysisType=savedType;$('#rankingPanel').hidden=!isProducts;['#metrics','.analysis-grid','.table-wrap','.definitions','#insightsView > .notice'].forEach(s=>{const el=s.startsWith('#insightsView')?$(s):$('#insightsView').querySelector(s);if(el)el.hidden=isProducts});$('#analyticsTabs').innerHTML=Object.entries(analysisNames).map(([k,n])=>`<button class="${k===analysisType?'selected':''}" data-analysis="${k}">${n}</button>`).join('');document.querySelectorAll('[data-analysis]').forEach(b=>b.onclick=()=>{analysisType=b.dataset.analysis;drawAnalysis()});$('#forecastPanel').hidden=analysisType!=='logistics';if(isProducts)drawRankings();if(analysisType==='logistics')drawForecast();$('#exportMetrics').hidden=isProducts;};$('#analysisMonth').onchange=drawAnalysis;$('#analysisChannel').onchange=drawAnalysis;$('#analysisProduct').onchange=drawAnalysis;
$('#insightsView .definitions').insertAdjacentHTML('beforeend','<p>품목·글로벌 채널 데이터는 기존 가상 실적을 일관된 배분 규칙으로 나눈 데모입니다. 실제 회사 실적·상품별 수익성을 나타내지 않습니다. 상품 순위와 예측은 별도의 가상 SKU 데이터셋이며 위 집계 실적과 직접 대사되지 않습니다.</p>');
const skuCatalog=[];const labels={jewelry:['로즈 펜던트','펄 이어링','슬림 브레이슬릿','루미 네크리스','데일리 스터드','레이어드 체인','미니 하트','클래식 펄','라운드 링크','쁘띠 포인트','소프트 골드','라인 실버'],bags:['미니 토트','아이보리 숄더','핑크 크로스','데일리 사첼','컴팩트 버킷','시티 토트','소프트 숄더','라이트 크로스','포켓 미니','베이직 호보','스퀘어 토트','슬림 파우치'],romanson:['실버 라운드','골드 클래식','레더 브라운','미니멀 블랙','데일리 메탈','화이트 다이얼','슬림 골드','네이비 레더','스퀘어 실버','클래식 듀얼','로즈 메탈','다크 브라운']};
Object.entries(labels).forEach(([category,names],ci)=>names.forEach((name,i)=>skuCatalog.push({id:category+'-'+i,category,name:'[샘플] '+name,price:[129000,159000,99000][ci]+i*10000,baseQty:260-i*18+ci*9,stock:80+i*35,type:i%3===0?'신상품':'러닝상품',image:ci*3+i%3,index:i})));
function rankedSkus(){const channel=$('#analysisChannel').value,month=+$('#analysisMonth').value,product=$('#analysisProduct').value;return skuCatalog.filter(s=>product==='all'||s.category===product).map(s=>{const qty=Math.max(1,Math.round((s.baseQty+(month===9?(s.index%4-2)*19:0))*({all:1,online:.4,offline:.45,global:.15}[channel])*(channel==='global'?(1+(s.index%3)*.25):1)));return {...s,qty,revenue:qty*s.price*.8}})}
function drawRankings(){const list=rankedSkus().sort((a,b)=>b.revenue-a.revenue||a.id.localeCompare(b.id));const top=list.slice(0,5),bottom=[...list].reverse().slice(0,5);$('#rankingPanel').innerHTML=`<div class="notice"><b>${productNames[$('#analysisProduct').value]} · ${$('#analysisChannel').selectedOptions[0].text} · ${$('#analysisMonth').selectedOptions[0].text}</b><p>순위 기준: 가상 순매출(판매수량 × 소비자가 × 80%). 상위는 내림차순, 하위는 오름차순입니다. ${list.length}개 가상 SKU 중 각 5개를 표시합니다. 상품명·가격·사진 모두 데모용이며 실제 판매상품이 아닙니다.</p></div><div class="rank-columns">${[['판매 상위 TOP 5',top],['판매 하위 TOP 5',bottom]].map(([title,items],gi)=>`<section><h3>${title}</h3>${items.map((s,i)=>`<article class="sku-card"><div class="sample-photo photo-${s.image}" role="img" aria-label="${productNames[s.category]} AI 생성 예시 사진"></div><div><span class="tag">${i+1}위 · ${productNames[s.category]} · ${s.type}</span><h4>${s.name}</h4><p>소비자가 ${fmt(s.price,0)}원 · 판매 ${fmt(s.qty,0)}개<br>가상 순매출 ${fmt(s.revenue/1e6)}백만원</p><small>${gi===0?'판매 기여도가 높은 후보. 가용재고·입고 예정 확인 후 보충 여부 검토.':'노출·가격·출시 경과일을 확인하고, 단순 판매량만으로 단종 판단 금지.'}</small></div></article>`).join('')}</section>`).join('')}</div><p class="small-note">사진: AI 생성 카테고리 예시를 반복 사용. 실제 품번별 이미지와 1:1 대응하지 않습니다.</p>`}
function drawForecast(){forecastPanel.innerHTML=`<div class="section-head"><div><span class="kicker">DEMAND & INVENTORY LAB</span><h2>신상품·러닝상품 판매 및 재고 대응</h2></div><span class="demo">단순 시나리오 · 예측 모델 미연결</span></div><div class="forecast-controls"><label>상품 구분 <select id="forecastType"><option>신상품</option><option>러닝상품</option></select></label><label>기준 주간 판매량 <input id="forecastSales" type="number" min="0" max="100000" value="40"></label><label>수요 변화율 (%) <input id="forecastGrowth" type="number" min="-80" max="200" value="10"></label><label>가용 재고 <input id="forecastStock" type="number" min="0" max="1000000" value="100"></label><label>확정 입고 예정 <input id="forecastInbound" type="number" min="0" max="1000000" value="20"></label><label>리드타임 (주) <input id="forecastLead" type="number" min="1" max="12" value="3"></label><label>안전재고 (개) <input id="forecastSafety" type="number" min="0" max="100000" value="30"></label></div><div id="forecastOutput" class="result"></div><p class="small-note">필터 범위: ${productNames[$('#analysisProduct').value]} / ${$('#analysisChannel').selectedOptions[0].text}. 범위 내 대표 상품을 가정한 입력값이며 실제 데이터 자동 조회는 아닙니다. 신상품은 유사 상품·초기 판매, 러닝상품은 최근 4주 평균을 기준으로 입력하세요.</p>`;forecastPanel.querySelectorAll('input,select').forEach(e=>e.oninput=updateForecast);updateForecast()}
function updateForecast(){const inputs=[...forecastPanel.querySelectorAll('input')];if(inputs.some(x=>x.value===''||!x.checkValidity())){$('#forecastOutput').textContent='허용 범위 내 숫자를 입력해 주세요.';return}const n=id=>Number($('#'+id).value),weekly=n('forecastSales')*(1+n('forecastGrowth')/100),available=n('forecastStock')+n('forecastInbound'),need=Math.max(0,Math.ceil(weekly*n('forecastLead')+n('forecastSafety')-available));$('#forecastOutput').textContent=`${$('#forecastType').value} · 향후 4주 판매 가정 ${Math.ceil(weekly*4)}개 (주당 ${fmt(weekly)}개)\n낮은 수요(-20%) ${Math.ceil(weekly*.8*4)}개 / 높은 수요(+20%) ${Math.ceil(weekly*1.2*4)}개\n4주 후 재고 가정 ${fmt(available-weekly*4)}개${available-weekly*4<0?' → 수요 대비 부족 예상':''}\n리드타임 내 보충 후보 ${need}개 = max(0, 예상 주간 판매 × 리드타임 + 안전재고 − 가용재고 − 확정 입고)\n\n${need>0?'대응: 입고일·MOQ·협력사 생산능력 확인 → 발주/이동안 검토 → 담당자 승인.':'대응: 추가 발주 전 판매 속도와 재고 연령을 모니터링.'}\n${$('#forecastType').value==='신상품'?'신상품 유의: 유사상품 적합성·런칭 프로모션·초기 표본 부족을 검토.':'러닝상품 유의: 품절 기간·시즌성·반품·행사 영향을 보정.'}\n※ 입고가 리드타임 내 도착한다고 가정. 자동 발주되지 않습니다.`}
