$('#workerCards').insertAdjacentHTML('beforeend',`<article class="worker-card"><span class="worker-icon">♡</span><span class="local-tag">사규 Q&A · 데모</span><h3>HR 헬퍼 · 제이케어</h3><p>휴가·휴직·평가·보상·사규를 묻는 창구</p><small>질문 → 주제 분류 → 확인 절차 안내</small><div class="worker-system">WORKS DRIVE 사규 / 그룹웨어 연동 구상</div><button class="primary" data-worker="hrhelp">HR 헬퍼에게 질문 ↗</button></article>`);document.querySelectorAll('[data-worker]').forEach(b=>b.onclick=()=>openWorker(b.dataset.worker));
const hrResponses={휴가:['휴가 신청과 잔여일수를 확인하고 싶으시군요.','휴가 종류·희망 기간을 확인한 후 그룹웨어의 잔여일수와 신청 경로를 확인하세요. 현재 데모는 개인별 잔여일수를 조회하지 않습니다.','휴가 규정 최신 시행본 / 신청·승인 절차'],휴직:['휴직 신청 요건과 절차가 궁금하시군요.','휴직 종류에 따라 요건·서류·급여 처리·복직 절차가 다릅니다. 종류와 희망 기간을 기준으로 인사팀에 확인할 항목을 정리해 주세요. 진단서 등 민감자료는 이 창에 입력하지 마세요.','휴직 규정 / 신청 서류 / 복직 안내'],평가:['평가 일정과 기준을 확인하고 싶으시군요.','해당 평가 기간·대상·평가 항목·피드백 및 이의신청 경로를 확인해야 합니다. 실제 평가 결과와 타인의 등급은 조회하지 않습니다.','평가 운영 공지 / 평가 기준 최신본'],보상:['보상 기준과 급여 관련 문의이군요.','연봉·성과급·수당은 적용 규정과 개인 계약에 따라 확인해야 합니다. 이 데모는 개인 연봉이나 인상률을 추정하지 않습니다. 본인 확인이 가능한 인사 문의 경로를 이용해 주세요.','보상 규정 / 본인 계약 / 급여 담당자'],사규:['적용되는 사규의 최신 버전 확인이 필요합니다.','문의 주제·적용 대상·시행일을 먼저 확인하고 승인된 원문을 찾아야 합니다. 규정이 충돌하거나 해석이 불명확하면 인사팀 확인을 거칩니다.','사규 문서 소유자 / 시행일 / 개정 이력']};
function openHr(){modal(`<h2>HR 헬퍼 · 제이케어</h2><p class="small-note">키워드 기반 체험 챗봇 · 실제 사규 검색/AI 미연결 · 입력은 외부 전송되지 않습니다.</p><div id="hrChat" class="hr-chat" role="log" aria-live="polite"><div class="chat-answer">안녕하세요. 휴가·휴직·평가·보상·사규 중 궁금한 주제를 알려주세요. 회사 규정 원문이 연결되기 전에는 절차와 확인 항목만 안내합니다.</div></div><div class="hr-chips">${Object.keys(hrResponses).map(t=>`<button data-hr="${t}">${t}</button>`).join('')}</div><form id="hrForm" class="search"><input id="hrQuestion" aria-label="HR 질문" placeholder="예: 휴가 신청은 어떻게 하나요?" maxlength="500" required><button>질문하기</button></form><p class="small-note">개인 급여·평가 결과·건강 정보는 입력하지 마세요. 대화는 창을 닫으면 사라집니다.</p>`,'HR HELPER');const respond=q=>{const found=Object.keys(hrResponses).filter(k=>q.includes(k));const key=found[0]||(/연차|반차/.test(q)?'휴가':/연봉|급여|수당|성과급/.test(q)?'보상':null);const text=key?hrResponses[key][0]+'\n\n'+hrResponses[key][1]+'\n\n확인할 근거: '+hrResponses[key][2]+'\n원문: 미연결 / 답변 상태: 담당자 확인 필요':'문의하신 내용은 이 데모에서 확인할 수 없습니다. 휴가·휴직·평가·보상·사규 중 주제를 선택하거나 인사팀에 문의해 주세요. 확인되지 않은 규정을 안내하지 않습니다.';$('#hrChat').insertAdjacentHTML('beforeend',`<div class="chat-question">${safe(q)}</div><div class="chat-answer">${safe(text)}</div>`);$('#hrChat').scrollTop=$('#hrChat').scrollHeight;$('#hrQuestion').value=''};$('#hrForm').onsubmit=e=>{e.preventDefault();const q=$('#hrQuestion').value.trim();if(q)respond(q)};document.querySelectorAll('[data-hr]').forEach(b=>b.onclick=()=>respond(b.dataset.hr+' 안내가 궁금해요.'))}
function openDerp(){modal(`<h2>DERP 전표 입력 어시스턴트</h2><p class="modal-desc">필수값 작성 → 차대변 검증 → DERP 형태 미리보기 자동입력</p><span class="local-tag">현재는 데모 화면에만 적용 · 실제 DERP 전송 없음</span><p class="small-note">첨부 화면의 필드를 참고했습니다. 아래 필수값은 데모 검증 기준이며 실제 전표유형별 필수값·코드는 회계/IT 확인이 필요합니다.</p><form id="derpForm"><div class="derp-fields">${field('unit','회계단위 *','text','제이에스티나')+field('date','회계일 *','date','2026-10-22')+field('department','작성부서 *','text','샘플 부서')+field('author','작성자 *','text','샘플 작성자')}<label class="field">전표유형 *<select name="type" class="control"><option>일반전표</option><option>개인비용 정산</option><option>계산서 비용전표</option></select></label>${field('summary','적요 *','text','업무용 소모품 구입')+field('vendorCode','거래처 코드 * (가상)','text','DEMO-V001')+field('vendor','거래처명 *','text','샘플 문구상사')+field('costCenter','비용센터 * (가상)','text','DEMO-CC01')+field('debit','차변 비용계정 * (가상)','text','DEMO-소모품비')+field('credit','대변 계정 * (가상)','text','DEMO-미지급금')+field('amount','비용금액 * (원)','number','50000','min="1" max="1000000000" step="1"')+field('tax','부가세 금액 * (직접 확인)','number','5000','min="0" max="1000000000" step="1"')}<label class="field">증빙 유형 *<select name="proof" class="control"><option>전자세금계산서 (샘플)</option><option>카드영수증 (샘플)</option><option>계산서 (샘플)</option></select></label>${field('proofId','증빙 식별번호 * (가상)','text','DEMO-P001')}<label class="field">프로젝트 (선택)<input class="control" name="project" placeholder="해당 시 입력"></label><label class="field">예산단위/예산계정 (선택)<input class="control" name="budget" placeholder="실제 필수 여부 확인"></label></div><label class="approval-check"><input type="checkbox" name="reviewed" required> 입력금액·증빙·계정 후보를 검토했습니다. (데모 확인)</label><button class="primary">검증 후 미리보기 자동채우기</button></form><div id="derpResult" aria-live="polite"></div><details class="definitions"><summary>실제 DERP 자동입력 연결에 필요한 사항</summary><p>① 회계/IT와 필드·계정·거래처 코드 및 전표유형별 필수값 확정 ② 공급사가 제공하는 전표 API/업로드 지원 확인 ③ API 미지원 시 회사가 승인한 RPA 또는 브라우저 확장 검토 ④ 사용자 인증·최소권한·테스트 환경 검증 ⑤ 사용자 승인 후 입력만 수행하고 저장·결재는 별도 확인.</p><p>외부 데모 페이지가 다른 도메인의 로그인된 ERP 화면을 직접 수정할 수는 없습니다. 입력 오류 시 중단·중복 생성 방지·작업 로그·원복 절차가 필요합니다. 아래 JSON은 연동 협의용 초안이며 DERP에 바로 업로드 가능한 형식이 아닙니다.</p></details>`,'DERP · ASSISTED ENTRY');$('#derpForm').oninput=()=>$('#derpResult').innerHTML='';$('#derpForm').onsubmit=e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target));if(Object.values(d).some(v=>typeof v==='string'&&!v.trim())&&['unit','department','author','summary','vendorCode','vendor','costCenter','debit','credit','proofId'].some(k=>!d[k]?.trim())){toast('필수 입력값을 확인해 주세요.');return}const amount=+d.amount,tax=+d.tax,total=amount+tax;const lines=[{side:'차변',account:d.debit,amount},...(tax?[{side:'차변',account:'부가세 계정 확인 필요',amount:tax}]:[]),{side:'대변',account:d.credit,amount:total}];$('#derpResult').innerHTML=`<div class="simulation-done">✓ 데모 미리보기 입력 완료 · 차변 ${fmt(total,0)}원 / 대변 ${fmt(total,0)}원 / 차액 0원</div><div class="erp-preview"><div class="erp-title">전표입력 미리보기 · 실제 ERP 아님</div><p>회계단위 ${safe(d.unit)} / 회계일 ${safe(d.date)} / ${safe(d.department)} / ${safe(d.author)}</p><p>전표유형 ${safe(d.type)} · 상태: 검토 초안 · 전표번호 미발급</p><div class="table-wrap"><table><thead><tr><th>차대</th><th>계정</th><th>적요</th><th>환종</th><th>금액</th><th>거래처</th><th>비용센터</th></tr></thead><tbody>${lines.map(l=>`<tr><td>${l.side}</td><td>${safe(l.account)}</td><td>${safe(d.summary)}</td><td>KRW</td><td>${fmt(l.amount,0)}</td><td>${safe(d.vendorCode)} / ${safe(d.vendor)}</td><td>${safe(d.costCenter)}</td></tr>`).join('')}</tbody></table></div><p>증빙: ${safe(d.proof)} / ${safe(d.proofId)}<br>프로젝트: ${safe(d.project||'미지정')} / 예산: ${safe(d.budget||'미지정')}</p></div><p class="small-note">부가세는 입력액 그대로 분리 표시한 예시입니다. 증빙 유형과 공제 여부에 따른 실제 분개는 회계 검토가 필요합니다.</p><div class="actions"><button class="outline" id="exportDerp">입력 데이터 JSON ↓</button><a class="outline" href="https://derp.jestina.com/FI/GLDDOC00500" target="_blank" rel="noopener noreferrer">DERP 전표 화면 열기 ↗</a></div><p class="small-note">링크는 화면만 엽니다. 실제 자동입력·저장·결재는 수행되지 않습니다.</p>`;$('#exportDerp').onclick=()=>downloadText('DERP-연동검토-샘플.json',JSON.stringify({demo:true,status:'draft_only',target:'DERP/FI/GLDDOC00500',header:d,currency:'KRW',lines,totalDebit:total,totalCredit:total},null,2),'application/json')}}
